  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (554::BIGINT, 'Muy buen profe conoce demasiado sobre la materia, el curso en sí tiene muchos trabajos, pero es muy bueno dando el laboratorio'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '25a0f473f0988ba49f80652a3407690d7df81b8d0648b94b919ed4652b901870'::TEXT, ARRAY[2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Johnny es buen profe, sabe muchísimo sobre química; tal vez no es el mejor explicando pero se la juega. He visto muchos comentarios aquí diciendo que es muy grosero pero, al menos con mi grupo, el mae era buena nota. Lo malo que tiene es que sale mucho del laboratorio (igual quedan los asistentes).'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'd972a642a30bdb6293eb3e5142cfe524626928eabcba58723718132b413a64b2'::TEXT, ARRAY[2738]::BIGINT[]),
    (554::BIGINT, 'Sinceramente, es una lástima que para lo mucho que sabe, trate tan mal a los estudiantes. Muchas veces su forma de hablar es humillante, ha hecho llorar a personas y además se cree superior, no acepta cuando se equivoca y ni siquiera le gusta que le hagan preguntas, para que lo tengan en cuenta :)'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2026-04-16T00:00:00+00:00'::TIMESTAMPTZ, 'f0fadbd179e135e7e52e8b8ff9b01f9d2e1527b8987e26218f6fad9903a4949f'::TEXT, ARRAY[1433, 2738]::BIGINT[]),
    (554::BIGINT, 'Es un excelente profesional y sabe, pero no tiene buena pedagogía. Sus clases son elevadas y puede llegar a explicar, pero califica demasiado duro, al punto que no tiene comparación lo que enseña con lo que te sale en un examen, mejor lee del Libro y complementalo con lo que el te da.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2025-08-16T00:00:00+00:00'::TIMESTAMPTZ, '3d3308d92b84f0757f2443e77f9f44adfd2c44890aebf832fb3fb4c83b2ddbdd'::TEXT, ARRAY[2737]::BIGINT[]),
    (554::BIGINT, 'Realmente es un excelente profe, suele ser un poco cerrado y un tanto robotico. Los quices son faciles si practica y lee el manual antes de clase. Cuestion de hacer todo bien y pasa con buena nota, no califiica duro'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '648711d403e47b64d4bfde43eb6cb379f7a3bab6a4f30610a6538474f373f78c'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Buen profe, sabe bastante, pero no saber enseñar bien. Califica más o menos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'cbf3f2c1a311eaf829277296852b4d719b4f3883c95f997048eba5350420298d'::TEXT, ARRAY[2738]::BIGINT[]),
    (554::BIGINT, 'Excelente profesor brinda buen apoyo. No le hagan caso a los comentarios negativos, eso es gente que no estudia y quieren que les regalen todo. En fin personas que no pueden con el nivel TEC'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-06-08T00:00:00+00:00'::TIMESTAMPTZ, '2f29f405d1fdd397fb812e5c36b590a6490681c14e06424dfcafd7ec5b1b9f41'::TEXT, ARRAY[2737]::BIGINT[]),
    (554::BIGINT, 'Sabe muchísimo pero a la vez es arrogante y no acepta que se equivoca, es capaz de humillar y tratar mal a los estudiantes y cuando se le pide ayuda se muestra molesto. Hace un desorden con los temas y las clases, el material de apoyo no es nada claro y evalúa cosas que practicamente no explicó.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-05-22T00:00:00+00:00'::TIMESTAMPTZ, '7c8d179ba74db8f50ce169c52b10c714886bd49e4551f4fc23fc88bf77f6d781'::TEXT, ARRAY[2737, 2738]::BIGINT[]),
    (554::BIGINT, 'No sé por qué la calificación de este profe es tan alta, el profesor es un egocéntrico que disfruta ver cómo los estudiantes hacen mal los ejercicios, no da temario para los exámenes y en los quices evalúa cosas que se mencionan de pasada pero lo califica como si se hubiese visto mucho el tema.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-05-16T00:00:00+00:00'::TIMESTAMPTZ, '104d96d200049c12090b3b602a43ee4e49aa55c946617b3984495f7f63a09479'::TEXT, ARRAY[2737]::BIGINT[]),
    (554::BIGINT, 'Este señor ya debería retirarse la verdad, si sabe mucho pero de que sirve si explica mal y solo quiere intimidar a los eztudiantes. Legalmente espero que pongan mejores profesores para orgánica y manden a este señor a ponerse para su casa. Entre silvia y el esta mejor el pero si puede evitelo.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-05-16T00:00:00+00:00'::TIMESTAMPTZ, '17eeb8320f18fb77c8915f950a231d22cc40cac7295343c4ef88531923cbf713'::TEXT, ARRAY[2737]::BIGINT[]),
    (554::BIGINT, 'Es excelente profe, califica justo, y tiene mucho conocimiento.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-20T00:00:00+00:00'::TIMESTAMPTZ, '9320aa3530cd96f48e831f3aa775a8d8db342e811bb57707d222bf6253370104'::TEXT, ARRAY[567, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'El profesor es excelente, ya que conoce muchísimo sobre el tema. Antes de cada laboratorio, da una clase de teoría, que apoya con la comprension de la clase. El profesor puede ser algo serio, algo malhumorado, pero si es un buen profesor. Sus criterios de calificación son muy rudos.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3f243bbee09864471383cdcb1b931e3eda2192bff86ec9323385e338228f6f44'::TEXT, ARRAY[2738]::BIGINT[]),
    (554::BIGINT, 'Le gusta que las cosas se hagan bien, y como es lab II se espera que no se cometan errores básicos, así que lleve la práctica clara y estudiada, además de para algunos exámenes cortos había que aprenderse reacciones y demás. Fue bastante amable y brindó ayuda, más si se va a hora consulta.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'ab08e81aff625749dfea99569ebfc984c024a1bf8f8b9a5247335982978cc919'::TEXT, ARRAY[613]::BIGINT[]),
    (554::BIGINT, 'El profe siempre se va del laboratorio, normalmente a estar con el teléfono, entonces durante los laboratorios no espere que el profesor le pueda estar ayudando, aveces anda de malas y no se soporta ni solo y aveces anda buena nota'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'b044d6c96e108ee989d99cb643add568bce0d44cbc9a29f86641416e45b1966f'::TEXT, ARRAY[1433, 2738]::BIGINT[]),
    (554::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c4fb00beb67878b377fd0530dcaed17bfd52cc7bde82bd7df27eabdec56141ac'::TEXT, ARRAY[2738]::BIGINT[]),
    (554::BIGINT, 'Es muy buen profesor, explica bien la materia y ayuda mucho. Se puede enojar con facilidad si uno no sigue sus instrucciones y es común que se vaya del laboratorio.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'bfa7e52167d282f7ffb97c54851ec001e6b51653b27294bd4aa9292b6132c777'::TEXT, ARRAY[2738, 1433]::BIGINT[]),
    (554::BIGINT, 'El profe es increible, cambio mucho en los ultimos años. Explica bien y ayuda en todo momento, incluso despues de clases se tomaba el tiempo de explicarnos un poco de teoría (aunque no era su trabajo) y nos resolvia dudas que teníamos. Si puede llevelo con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2022-07-24T00:00:00+00:00'::TIMESTAMPTZ, '35462fde96ca270059dd8b679bd00667a788ce2b84b06e1dd6829c7cea948b53'::TEXT, ARRAY[2738]::BIGINT[]),
    (554::BIGINT, 'Me comentaron que el mae cambio mucho en años anteriores, porque a mi me pareció super buena nota el profe, si tiene sus cosas, si usted no hace lo que el pide o anda perdiendo el tiempo el mae si se enoja rápido pero además de eso excelente profe, las explicaciones uff 10/10'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, '957bdaf8e87205caa723f27b3edfd0ecb414e7701742d5a092647bcbb08579d1'::TEXT, ARRAY[1433, 2738]::BIGINT[]),
    (554::BIGINT, 'Es muy bueno. Se nota la experiencia que tiene, las clases presenciales fueron geniales, las remotas buenas, pero no se pueden comparar una clase detrás de una computadora con estar haciendo y trabajando en un lab. Un poquito acelerado, pero es su personalidad. Muy recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '9a8d82698950307121eeaf33250864757aaeb7e6b9f1f2638d3e3fa40513f840'::TEXT, ARRAY[1433, 2738]::BIGINT[]),
    (554::BIGINT, 'El profe es super lindo, realmente inspira mucho y sabe demasiado. Es considerado con los estudiantes y se nota que ama lo que hace. En ocasiones es desordenado con las fechas pero usted debe andar preguntándole. Lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '89712bbaa9c3000ea15a11db7e21b46d8618ace3b66629e7593a0577d7fe14b2'::TEXT, ARRAY[1433, 2738]::BIGINT[]),
    (554::BIGINT, 'El profe explica bien la materia, califica bien, solo es un poco desordenado con respecto a fechas de entrega, a veces deja cosas con poco tiempo, y tome en cuenta que le va tocar viajar porque el curso es semipresencial'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c6ca55836f443ebe4581af328b92b144bd22fa1ad233f0bcec94d78b90a27e51'::TEXT, ARRAY[1433, 2738]::BIGINT[]),
    (554::BIGINT, 'Es un excelente profesor, hace muchos quices , pero el profesor ayuda muchísimo, explica muy bien y hay que estudiar y hacer las prácticas además de utilizar el libro para pasar excelente el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'f88242c31d0b33b4e0e2553598d4e21b1bfa9dc03f367a7e8f0c17059944f581'::TEXT, ARRAY[2737]::BIGINT[]),
    (554::BIGINT, 'Excelente profesor. Tuvo que vivir esa dura transición de lo presencial a lo virtual, lo cual a veces le jugó malas pasadas pero salia adelante como lo grandes. Muy comprometido con la enseñanza, interesado en que el estudiante aprenda . Recomendado 100%'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'b17666a4786f82b22febc02e6319cac3d11b3f67f7bd5e6b8877557ce6023b38'::TEXT, ARRAY[1433]::BIGINT[]),
    (554::BIGINT, 'Pasar con él es relativamente fácil, solo haga las cosas tal y como él las pide. Se enoja muy fácilmente en las clases(virtuales). A mi me pasó que perdió algunos trabajos y nos obligaba a volverlos a hacer o a incomodarnos nosotros cuando fue falta de él pero nada del otro mundo. Es promedio'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '659d7b47a9362e5716cf31b6cb38593df50ac93d034faef1b816b39d850a77a4'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Excelente profesor, se nota que le gusta mucho el área y se esfuerza para que el estudiante adquiera conocimientos más allá del curso. Es muy sarcastico, pero buena gente. Esta dispuesto a ayudarte en lo que necesites.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '467e1c4ae8a7831cfa489d29ea01647b0bae2a49f85a0f7cde1a40f55bfeaf69'::TEXT, ARRAY[2738]::BIGINT[]),
    (554::BIGINT, 'Es buen profe, pero de vez en cuando tiene problemas con las app para dar clases, y se enoja rarísimo con uno. Pero no es dificil pasar con él'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '77710ab832ab4a2a79af10ca339be6ec24e1863fbe00c2e75ee2e5ac7b5a7db2'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '19307caf4b3b32ccf145fa08bfdff4945ce509a2f887a7c71de69258e674c409'::TEXT, ARRAY[2738, 1433]::BIGINT[]),
    (554::BIGINT, 'El profe es muy buena nota, siempre le va a contestar los correos, es un poco repugnante en ciertas ocasiones en clase, pide participación, pero en si siempre está dispuesto a aclarar las dudas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'c6f2d85492cff930ce428c59451def553e948fda5f366edcbd8025238d63809b'::TEXT, ARRAY[1433, 2738]::BIGINT[]),
    (554::BIGINT, 'El curso es muy accesible para llevarlo virtual, pero debo decir que el profesor aveces reacciona de una forma muy grosera, unos compañeros le preguntan algo y el responde de mala gana y enojado. Él sí se nota que intenta ayudar pero aveces reacciona muy feo cuando esta estresado'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'd3c1e8358e2f50e48d9bebb89d2d82f8f9eae8add8acf3c0af5ec7dba4e719f7'::TEXT, ARRAY[1433]::BIGINT[]),
    (554::BIGINT, 'Es excelente profe, se esforzó mucho porque aprendiéramos. Presentaciones y video que permitieron una excelente transmisión del conocimiento. Muy comprometido con la enseñanza de los estudiantes. Aprendí muchísimo. Modo virtual 10/10.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-08-12T00:00:00+00:00'::TIMESTAMPTZ, 'c5236911ac3991add696278aa289a45de2ceaee9c6c2628c253760dddb500b57'::TEXT, ARRAY[2738, 1433]::BIGINT[]),
    (554::BIGINT, 'El profe es súper bueno, explica con mucha claridad y te explica todas las veces que necesites. Los exámenes virtuales los hace muy claros y si estudiaste lo ves súper fácil al igual que los quices. Tiende a extenderse un poco en las clases pero la verdad que es una de los mejores de la escuela'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'de38de45ea1a452f0123ee9cffe464175ae4eb2001e7f75df6662de1cf2d59eb'::TEXT, ARRAY[1433]::BIGINT[]),
    (554::BIGINT, 'Es un excelente profesor, realmente se esfuerza mucho por sus estudiantes y realmente explica de maravilla. Lo recomendari?a una y mil veces!! Seguimos todos juntos en el barco'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '3531e4dd1ad12a132842080e1600815220e024ee96952ffce2a9db7f6d149461'::TEXT, ARRAY[1434]::BIGINT[]),
    (554::BIGINT, 'Es muy serio, pero con el tiempo puede volverse amigable si se le permite. Se preocupa por el estudiante y siempre intenta ayudar a quien le demuestra interés en el curso. Las anécdotas de su experiencia académica y laboral son inspiracionales. 100% recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '06ce3b97b46f3a4f8c5a1032a2a52ea3e34dcbcf3c42446482902c5403b76da8'::TEXT, ARRAY[2738]::BIGINT[]),
    (554::BIGINT, 'Excelente profesional, un poco serio, pero con el paso del tiempo se vuelve más llevadero, si hay que estudiar para los quices, aveces son muy especificos con la materia, él toma en cuenta la libreta como parte del quiz, todas la semanas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '9e971372b87928e79397dfd7ef807f68a39a238b9a3c4e64b12cd20ca2c9ac5f'::TEXT, ARRAY[613]::BIGINT[]),
    (554::BIGINT, 'El profe es un toque serio, pero con el tiempo uno se lleva mejor con él. Califica normal. Creo que es de los pocos profes que realmente contesta todos los correos que uno le envía y que siempre brinda ayuda. Me parece un excelente profesional :)'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2019-07-25T00:00:00+00:00'::TIMESTAMPTZ, '65dda7a0522c4496dce26369fc8685b8b3daf24fa1695cfb73639f512b21e5c5'::TEXT, ARRAY[2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Lleve lab con el y es un excelente profe. Algo serio al principio pero se vuelve muy amigable con cada clase. Muy flexible con los trabajos e informes. Hace el curso fácil. Hace quices pero no son complicados.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '392c3e01f2cd4ba952b85813297b6f91ee3ce16d484fe213c32a4e3360156fb5'::TEXT, ARRAY[613]::BIGINT[]),
    (554::BIGINT, 'Un gran profesor, se esmera porque los estudiantes entiendan todo, explica muy bien. Un poco serio y estricto pero muy buena persona'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-05T00:00:00+00:00'::TIMESTAMPTZ, '8657a9ff8cfd34b3d8c1ec528873415c4fb4372a749aa2f805ccdc53a80c1d53'::TEXT, ARRAY[613]::BIGINT[]),
    (554::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-20T00:00:00+00:00'::TIMESTAMPTZ, 'dcbdd7f358a614a9c54e90de3b7a05b2fc0a30dd681f70c1551e1ea18d845fd4'::TEXT, ARRAY[613]::BIGINT[]),
    (554::BIGINT, 'Muy bueno, le gusta orgánica entonces se le puede preguntar cualquier cosa del curso. Un poco estricto pero buena persona.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-05T00:00:00+00:00'::TIMESTAMPTZ, '4ab9a8a88a6e25b6da53dca58eb66009f4ae0341ca9f5eaf4d91e3ce14f28a22'::TEXT, ARRAY[1433, 2738]::BIGINT[]),
    (554::BIGINT, 'Buen profe, el curso se pasa vacilón, solo no haga preguntas tontas y estudiese las practicas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'e3d9ddf19a777658df6428bf5767a8ffd71dd2925c6141a8834af93e47b3a58f'::TEXT, ARRAY[1433, 2738]::BIGINT[]),
    (554::BIGINT, 'No se porqué tiene tan baja calificación. El curso se hace muy sencillo con él, explica muy bien y es una excelente persona. Deja los informes para la casa en varias ocasiones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-14T00:00:00+00:00'::TIMESTAMPTZ, '02d06b1e3a853f7ee5e40e419a70d88084bc31518f069a12393c0634d2e7ac23'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Buenísimo profesor, se ve serio pero a medida que avanza el semestre se vuelve hasta gracioso. Le encanta orgánica y eso lo demuestra mucho.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'e5470d1df7669613abccd489250400fe5f8dfc40c33710f861311cfad0957137'::TEXT, ARRAY[2738]::BIGINT[]),
    (554::BIGINT, 'Es serio y aburrido explicando pero si demuestran interés se lo ganan y se convierte en un profe que ustedes nunca van a olvidar. Califica informes suave y ayuda montones si lo buscan.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4e6dedc26dd7e791408d1a900f5b84c5399af6b046b6695f48d6e8c76447c9e0'::TEXT, ARRAY[2738]::BIGINT[]),
    (554::BIGINT, 'El profe es un poco odioso pero el curso no es tan difícil con él. Es un poco flexible con la entrega de los informes y hace quices en pareja a veces. No califica suave pero explica bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd8f4a3d1669e845ca2977819ddeb4ccb9acc5b222e5c761a712ba322c71bd49a'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Al principio las clases son aburridas pero conforme pasa el semestre se relaja un poco. Hay que tomarse el laboratorio en serio porque el se fija mucho en el interés del estudiante'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '353d5f347f3332882fe2af89ffee44d45762b4c0d9067a17b49e8e216796be8f'::TEXT, ARRAY[2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Sin duda el mejor profesor para el laboratorio. Los quices son muy fáciles, da tiempo para los informes y es demasiado bueno.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-05T00:00:00+00:00'::TIMESTAMPTZ, '142af9dc1356cdb772494b9c7a0df2f1d09b9eb78b52c18f64d0e46735fa99cd'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Es estricto calificando, pero aclara muy bien las dudas. Es poco odioso cuando le preguntan muchas veces algo. Hace quizes en parejas y permite que se entregue el informe al día siguiente si no queda mucho tiempo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-05T00:00:00+00:00'::TIMESTAMPTZ, '16323fc12cac2d56d899eb3b2dc5a8686f84395fa1fe7bdffc0ea6a0988f8c4a'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Johnny es el mejor profe de lab, FIGHT ME. Conforme pasa el semestre, se vuelve más amigable y un segundo papá. No sean mediocres, él solo quiere ver a los mejores profesionales'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2018-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'c2839ab779661e164dbc94eef2b79b47eb66cda1f54f9f9b047e9e4841f29e96'::TEXT, ARRAY[1433, 2738]::BIGINT[]),
    (554::BIGINT, 'Es un tanto odioso aunque si explica cómo debe, es muy duro calificando!'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '7b9e8a62b22aaeff99d866ac868726e1b0ede1bb8ee016933aa52b8ef7665644'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Un suplicio con este profe'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-26T00:00:00+00:00'::TIMESTAMPTZ, '6e382e0f3a20c77d29405976da98988bffda14b681208ff5b6bea33d28c530d6'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Es un profesor muy prepotente, no perdona nada en los informes.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, '78219d215715438ad0bf5047edc0a503755d554508db14f9373b16b4bfb0947d'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
