    (554::BIGINT, 'Un profe odioso y muy estricto'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, '7c6394bd67cb129238c97c247c715490b859847358e20cb08e6f56d655adff99'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Regular, es muy estricto'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'c536820f4b84f4072f611e2359e7ef725837c9bcf1405258195710ee4b305be4'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
