    (554::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa']::TEXT[], '2018-01-23T00:00:00+00:00'::TIMESTAMPTZ, '9c0ecf6b9c9242e92f831a05bfde03c7507895ef6c84dc8bf1997b6333f03983'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Explica bien, pero es súper estricto, califica duro y no regala pero ni lo que le sobra.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-22T00:00:00+00:00'::TIMESTAMPTZ, '11eb91b0245c3aab31b922aab07bfa2e01310041a21d9e585780d7d88f4447af'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
