    (554::BIGINT, 'Explica bien, califica muy duro.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'f182b1ca05003b109d6e95b4bd0a990b0af9b84da4782649c874f8eef0abe772'::TEXT, ARRAY[567, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Malísimo, súper estricto y repugnante!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'ce8bb3e953936236574139c24acc03caecf2c5a5fb76e62e30c0de30bb1a5fe9'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Super estricto no ayuda'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'd332525e2a571989b54e7ec385c3de1f774b5cbe46db2a07bdb46e6548c4ec83'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Serio pero explica de que trata los laboratorios, además el informe aveces se podía entregar al día siguiente. Estricto pero excelente. Muy recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '562b4f4ded2c3c894e84d449dc9b3c11c8f5e59927a69e05e692ab1949d7b5dd'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'es serio y buena gente, solo que no tolera la estupidez, pero no se hace pesado el curso'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'd294cff867646d49988485332d0748b95cb7e4833778b77dcff09033c00320fc'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Es un tanto odioso pero eso no genera problema con respecto al curso. SIEMPRE explica todo antes del lab y ayuda con los informes. Se hace relajado el curso'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'bbae366cee3dd86e0a08690a7f78fb2f85adcc8da8fa96a91aa44f50b1278a2a'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Pase y nose como, es bastante pasable.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '307d20f61289cbafb2c30eebe17775bad24897a6c92938464868baaa4d4170a1'::TEXT, ARRAY[567, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'Excelente profe. Hay que tener disposición por aprender y poner atención en la clase de teoría, pero hace que el laboratorio sea fácil y ordenado y sabe un montón. Es serio, pero muy recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'd86ef464885718adcb554ca36e8b1edcbd52859203fd89b237792792ba5dc33b'::TEXT, ARRAY[613]::BIGINT[]),
    (554::BIGINT, 'Excelente profesor! explica muy claro y es muy buena gente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'ac4dd03f79004ada6dc47f8cd6721c5a2f80735faaf91f5c52581e3494b88b39'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
