    (554::BIGINT, 'Es muy importante tener buen conocimiento de la practica ya que hace bastantes preguntas al grupo. Muestra en cada informe que cosas se tienen que corregir y eso ayuda en el examen. Muy recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-22T00:00:00+00:00'::TIMESTAMPTZ, '95b9f7ed113e4dc8f59ccd7e211cc68eed9fcada622934c6a22bdd81a7f851f9'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
