    (554::BIGINT, 'Algunas veces cuesta entenderle pero se puede pasar fácil con él'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'f23f2ca296a69bd9bc6b3f0c91c8f162725ee5a511a3f6ed2a1568f95f23e443'::TEXT, ARRAY[567, 2738, 1433]::BIGINT[]),
    (554::BIGINT, 'No es el mejor a la hora de dar Lab, sin embargo esta pendiente de sus alumnos y lo ayuda a uno.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-05T00:00:00+00:00'::TIMESTAMPTZ, '3ec0f0adbe79a87b4ea58bd1dd61559c358c253b1af7f5a3ec53b0bc6761cc1e'::TEXT, ARRAY[613, 2738, 1433]::BIGINT[]),
